INSERT INTO public.recipes (household_id, title, meal_type, ingredients, steps, points) VALUES
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Soupe thaï au lait de coco et gingembre$t$, 'diner', $j$[{"name":"400 ml de lait de coco","quantity":""},{"name":"500 ml de bouillon de légumes ou de poulet","quantity":""},{"name":"1 pavé de saumon sauvage (ou crevettes)","quantity":""},{"name":"Gingembre frais (3 cm)","quantity":""},{"name":"2 gousses d’ail","quantity":""},{"name":"1 citronnelle (ou zeste de citron vert)","quantity":""},{"name":"Champignons au choix","quantity":""},{"name":"Coriandre fraîche, ciboulette","quantity":""},{"name":"Sauce soja, jus de citron vert","quantity":""},{"name":"Piment doux (optionnel)","quantity":""}]$j$::jsonb, $j$["Faites revenir l’ail pressé et le gingembre râpé dans un peu d’huile de coco, 2 minutes.","Ajoutez le bouillon et la citronnelle écrasée, portez à frémissement.","Versez le lait de coco, ajoutez les champignons. Laissez mijoter 10 min à feu doux.","Ajoutez le saumon en dés ou les crevettes. Cuisez 5 min supplémentaires.","Assaisonnez avec la sauce soja et le jus de citron vert.","Servez parsemé de coriandre fraîche et de ciboulette. Accompagnez de nouilles de riz ou de riz basmati blanc."]$j$::jsonb, 15),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Curry de légumes au curcuma$t$, 'diner', $j$[{"name":"1 boîte de tomates concassées","quantity":""},{"name":"400 ml de lait de coco","quantity":""},{"name":"1 patate douce en dés","quantity":""},{"name":"1 courgette, 1 poivron rouge","quantity":""},{"name":"1 oignon, 3 gousses d’ail","quantity":""},{"name":"1 càs de curcuma","quantity":""},{"name":"1 càc de cumin","quantity":""},{"name":"1 càc de gingembre en poudre","quantity":""},{"name":"1 càc de paprika doux","quantity":""},{"name":"Huile de coco, sel, poivre","quantity":""},{"name":"Riz basmati blanc","quantity":""}]$j$::jsonb, $j$["Faites revenir l’oignon émincé et l’ail dans l’huile de coco, 3 minutes.","Ajoutez toutes les épices, mélangez 1 minute pour les torréfier légèrement.","Ajoutez la patate douce, les tomates et le lait de coco. Portez à ébullition.","Réduisez à feu doux, ajoutez courgette et poivron. Mijotez 20 min à couvert.","Rectifiez l’assaisonnement et servez sur du riz basmati. Ajoutez des pois chiches rincés pour un apport protéique végétal."]$j$::jsonb, 15),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Bowl sardines, avocat et quinoa$t$, 'dejeuner', $j$[{"name":"1 boîte de sardines à l’huile d’olive","quantity":""},{"name":"1/2 avocat","quantity":""},{"name":"80 g de quinoa cuit (ou riz basmati froid)","quantity":""},{"name":"Tomates cerises, concombre","quantity":""},{"name":"Câpres, oignon rouge","quantity":""},{"name":"Jus de citron, huile d’olive","quantity":""},{"name":"Graines de courge ou de chanvre","quantity":""},{"name":"Aneth, ciboulette","quantity":""},{"name":"Sel de l’Himalaya, poivre","quantity":""}]$j$::jsonb, $j$["Rincez le quinoa et cuisez-le 12 min dans 2 fois son volume d’eau. Laissez refroidir.","Disposez le quinoa dans un bol, ajoutez les légumes coupés.","Émiettez les sardines par-dessus, ajoutez l’avocat en tranches.","Parsemez de câpres, d’oignon rouge finement émincé, de graines et d’herbes.","Arrosez de jus de citron et d’un filet d’huile d’olive. Assaisonnez."]$j$::jsonb, 10),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Bol açaï anti-inflammatoire$t$, 'petit_dej', $j$[{"name":"2 càs de poudre d’açaï (ou 1 sachet surgelé)","quantity":""},{"name":"1/2 banane mûre congelée","quantity":""},{"name":"100 ml de lait de coco ou d’amande","quantity":""},{"name":"Myrtilles, framboises surgelées","quantity":""},{"name":"Granola d’oléagineux","quantity":""},{"name":"Noix de coco râpée","quantity":""},{"name":"Graines de chia","quantity":""},{"name":"Chocolat 85 % râpé","quantity":""},{"name":"Noix de macadamia","quantity":""}]$j$::jsonb, $j$["Mixez la poudre d’açaï, la banane congelée, les fruits rouges et le lait végétal jusqu’à obtenir une texture épaisse et crémeuse.","Versez dans un bol — la consistance doit être plus épaisse qu’un smoothie.","Disposez joliment les garnitures : granola, coco râpée, chia, chocolat.","Dégustez immédiatement.","Jour d’entraînement : ajoutez 1 càs de purée d’amandes pour un apport lipidique plus soutenu."]$j$::jsonb, 5),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Omelette soufflée épinards et chèvre affiné$t$, 'diner', $j$[{"name":"3 oeufs","quantity":""},{"name":"1 grosse poignée d’épinards frais","quantity":""},{"name":"30 g de chèvre affiné émietté","quantity":""},{"name":"1 gousse d’ail","quantity":""},{"name":"Basilic, ciboulette","quantity":""},{"name":"Huile de coco ou ghee bio","quantity":""},{"name":"Sel de l’Himalaya, poivre","quantity":""},{"name":"Noix de muscade (optionnel)","quantity":""}]$j$::jsonb, $j$["Séparez les blancs des jaunes. Montez les blancs en neige ferme avec une pincée de sel.","Mélangez les jaunes avec les épinards hachés, l’ail pressé, les herbes et les épices.","Incorporez délicatement les blancs en neige, sans casser la mousse.","Chauffez le ghee dans une poêle. Versez, couvrez et cuisez 4-5 min à feu doux.","Émiettez le chèvre dessus, couvrez encore 2 minutes.","Servez avec une salade verte."]$j$::jsonb, 15),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Crackers aux graines et herbes$t$, 'collation', $j$[{"name":"100 g de graines de tournesol","quantity":""},{"name":"80 g de graines de courge","quantity":""},{"name":"60 g de graines de sésame","quantity":""},{"name":"60 g de graines de lin entières","quantity":""},{"name":"2 càs de psyllium blond","quantity":""},{"name":"180 ml d’eau","quantity":""},{"name":"Romarin, thym, origan séché","quantity":""},{"name":"Sel de l’Himalaya, poivre","quantity":""},{"name":"1 càs d’huile d’olive","quantity":""}]$j$::jsonb, $j$["Mélangez toutes les graines avec le psyllium, les herbes, le sel et l’huile.","Ajoutez l’eau, mélangez, laissez gonfler 10 min — la pâte doit être compacte.","Étalez très finement (2-3 mm) sur une plaque avec papier sulfurisé.","Marquez des lignes au couteau pour prédécouper.","Cuisez 45-55 min à 150°C jusqu’à ce que ce soit bien sec et doré.","Laissez refroidir complètement avant de casser."]$j$::jsonb, 5),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Pudding de chia façon golden milk$t$, 'collation', $j$[{"name":"250 ml de lait de coco","quantity":""},{"name":"3 càs de graines de chia","quantity":""},{"name":"1 càc de curcuma en poudre","quantity":""},{"name":"1/2 càc de gingembre en poudre","quantity":""},{"name":"1 pincée de poivre noir","quantity":""},{"name":"1 càc de miel artisanal cru","quantity":""},{"name":"Vanille en poudre","quantity":""},{"name":"Myrtilles, coco râpée, amandes effilées (garniture)","quantity":""}]$j$::jsonb, $j$["Mélangez le lait de coco avec curcuma, gingembre, poivre, vanille et miel.","Ajoutez les graines de chia et mélangez bien pour éviter les grumeaux.","Versez dans un bocal, couvrez, réfrigérez minimum 6 h (idéalement une nuit).","Le matin, mélangez à nouveau ; détendez avec un peu de lait si trop épais.","Garnissez de myrtilles, coco râpée et amandes effilées."]$j$::jsonb, 5),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Velouté de betterave, coco et gingembre$t$, 'diner', $j$[{"name":"3 betteraves cuites (ou crues)","quantity":""},{"name":"400 ml de lait de coco","quantity":""},{"name":"200 ml de bouillon de légumes","quantity":""},{"name":"Gingembre frais (2 cm)","quantity":""},{"name":"1 oignon","quantity":""},{"name":"2 gousses d’ail","quantity":""},{"name":"Jus d’1/2 citron","quantity":""},{"name":"Huile de coco, sel, poivre","quantity":""},{"name":"Graines de courge, ciboulette (finition)","quantity":""}]$j$::jsonb, $j$["Faites revenir l’oignon et l’ail dans l’huile de coco, 3 minutes.","Ajoutez les betteraves en dés et le gingembre râpé, faites revenir 2 min.","Versez le bouillon, portez à ébullition, mijotez 15 min (10 min si betteraves cuites).","Ajoutez le lait de coco et mixez jusqu’à texture lisse.","Ajoutez le jus de citron, rectifiez l’assaisonnement.","Servez chaud avec graines de courge et ciboulette."]$j$::jsonb, 15),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Energy balls datte, amande et cacao$t$, 'collation', $j$[{"name":"150 g de dattes Medjool dénoyautées","quantity":""},{"name":"100 g de poudre d’amandes","quantity":""},{"name":"2 càs de cacao 100 % pur","quantity":""},{"name":"1 càs de purée d’amandes","quantity":""},{"name":"1 pincée de sel de l’Himalaya","quantity":""},{"name":"1 pincée de cannelle","quantity":""},{"name":"Noix de coco râpée (pour rouler)","quantity":""},{"name":"Optionnel : 1 càs de graines de chanvre","quantity":""}]$j$::jsonb, $j$["Mixez les dattes jusqu’à obtenir une pâte collante.","Ajoutez poudre d’amandes, cacao, purée d’amandes, sel et cannelle. Mixez à nouveau.","Trop sec : ajoutez 1-2 càs d’eau. Trop collant : ajoutez de la poudre d’amandes.","Formez des boules de la taille d’une noix avec les mains légèrement humides.","Roulez dans la noix de coco râpée.","Réfrigérez 1 h minimum. Se conservent 2 semaines au frigo."]$j$::jsonb, 5),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Smoothie vert anti-inflammatoire$t$, 'petit_dej', $j$[{"name":"1 grosse poignée d’épinards frais","quantity":""},{"name":"1/2 concombre","quantity":""},{"name":"1 banane mûre congelée","quantity":""},{"name":"200 ml de lait de coco ou d’amande","quantity":""},{"name":"1 càs de graines de chia","quantity":""},{"name":"1 càs de purée de noix de cajou","quantity":""},{"name":"Jus d’1/2 citron vert","quantity":""},{"name":"Gingembre frais (1 cm)","quantity":""},{"name":"1 càc de spiruline (optionnel)","quantity":""}]$j$::jsonb, $j$["Placez tous les ingrédients dans un blender, les liquides en premier.","Mixez 60 secondes jusqu’à texture parfaitement lisse.","Goûtez et ajustez : plus de citron pour l’acidité, plus de banane pour le sucré.","Consommez immédiatement pour préserver les nutriments."]$j$::jsonb, 5),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Tartare de thon au sésame et gingembre$t$, 'dejeuner', $j$[{"name":"200 g de thon frais qualité sashimi","quantity":""},{"name":"1 càs de sauce soja","quantity":""},{"name":"1 càs d’huile de sésame","quantity":""},{"name":"1 càc de gingembre frais râpé","quantity":""},{"name":"1 càc de graines de sésame grillées","quantity":""},{"name":"1/2 avocat en dés","quantity":""},{"name":"Ciboulette, oignons nouveaux","quantity":""},{"name":"Jus de citron vert","quantity":""}]$j$::jsonb, $j$["Coupez le thon en petits dés réguliers au couteau bien aiguisé.","Mélangez sauce soja, huile de sésame, gingembre et jus de citron vert.","Versez la marinade sur le thon, mélangez délicatement, laissez 5 min.","Ajoutez l’avocat et les oignons nouveaux, mélangez.","Dressez à l’emporte-pièce, parsemez de sésame et de ciboulette.","Servez immédiatement avec crackers aux graines ou salade."]$j$::jsonb, 10),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Poêlée de chou kale, lardons et noix$t$, 'diner', $j$[{"name":"1 belle botte de chou kale","quantity":""},{"name":"100 g de lardons artisanaux non salés","quantity":""},{"name":"1 oignon rouge","quantity":""},{"name":"2 gousses d’ail","quantity":""},{"name":"1 poignée de noix concassées","quantity":""},{"name":"1 càs de vinaigre de cidre","quantity":""},{"name":"Huile d’olive","quantity":""},{"name":"Sel de l’Himalaya, poivre","quantity":""},{"name":"Parmesan râpé (optionnel)","quantity":""}]$j$::jsonb, $j$["Lavez le kale, retirez les tiges épaisses, déchirez les feuilles.","Faites dorer les lardons à sec dans une grande poêle.","Ajoutez l’oignon émincé et l’ail dans la graisse des lardons, 3 minutes.","Ajoutez le kale en plusieurs fois — il réduit beaucoup. 5-7 min à feu moyen.","Déglacez au vinaigre de cidre, assaisonnez.","Servez parsemé de noix concassées et de parmesan."]$j$::jsonb, 15),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Bouillon d’os maison$t$, 'diner', $j$[{"name":"1,5 kg d’os de boeuf ou carcasse de poulet (élevage plein air)","quantity":""},{"name":"2 càs de vinaigre de cidre","quantity":""},{"name":"2 carottes, 2 branches de céleri","quantity":""},{"name":"1 oignon (avec la peau)","quantity":""},{"name":"2 gousses d’ail","quantity":""},{"name":"1 feuille de laurier, thym","quantity":""},{"name":"Quelques grains de poivre","quantity":""},{"name":"3 litres d’eau froide","quantity":""},{"name":"Sel de l’Himalaya (en fin de cuisson)","quantity":""}]$j$::jsonb, $j$["Optionnel mais conseillé : faites rôtir les os 30 min à 200°C pour plus de goût.","Placez les os dans une grande marmite, couvrez d’eau froide, ajoutez le vinaigre. Laissez reposer 30 min — l’acidité aide à extraire les minéraux.","Portez à frémissement, écumez la mousse qui remonte.","Ajoutez légumes et aromates. Laissez mijoter à tout petit feu : 12 à 24 h pour le boeuf, 6 à 12 h pour le poulet.","Filtrez, salez, laissez refroidir. Retirez la couche de gras figée si vous le souhaitez.","Conservez 5 jours au frigo ou congelez en portions."]$j$::jsonb, 15),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Bouillon de légumes maison$t$, 'diner', $j$[{"name":"2 carottes, 2 branches de céleri","quantity":""},{"name":"2 oignons (avec la peau, lavée)","quantity":""},{"name":"1 poireau (le vert aussi)","quantity":""},{"name":"3 gousses d’ail","quantity":""},{"name":"1 morceau de gingembre (2 cm)","quantity":""},{"name":"Champignons ou pieds de champignons","quantity":""},{"name":"Laurier, thym, persil (tiges)","quantity":""},{"name":"1 càs d’huile d’olive","quantity":""},{"name":"2,5 litres d’eau","quantity":""},{"name":"Sel de l’Himalaya, poivre en grains","quantity":""}]$j$::jsonb, $j$["Coupez grossièrement tous les légumes, sans les éplucher (lavez-les bien).","Faites-les revenir 5 min dans l’huile d’olive pour développer les saveurs.","Couvrez d’eau froide, ajoutez les aromates.","Portez à ébullition puis laissez mijoter 45 min à couvert.","Filtrez en pressant les légumes pour extraire les sucs. Salez.","Conservez 5 jours au frigo ou congelez en portions."]$j$::jsonb, 15),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Ghee maison (beurre clarifié)$t$, 'dejeuner', $j$[{"name":"250 g de beurre bio de qualité (idéalement au lait cru, de ferme)","quantity":""}]$j$::jsonb, $j$["Coupez le beurre en morceaux dans une casserole à fond épais.","Faites fondre à feu très doux, sans remuer. Le beurre va se séparer en 3 couches.","Une mousse blanche se forme en surface : écumez-la délicatement à la cuillère.","Laissez cuire doucement 15-20 min : les dépôts blancs (caséine) tombent au fond et dorent légèrement. Le ghee est prêt quand le liquide est doré, clair, et sent la noisette.","Filtrez à travers une étamine ou un filtre à café dans un bocal en verre.","Se conserve plusieurs mois à température ambiante, à l’abri de la lumière."]$j$::jsonb, 10),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Mayonnaise maison à l’huile de colza$t$, 'dejeuner', $j$[{"name":"1 jaune d’oeuf (à température ambiante)","quantity":""},{"name":"1 càc de moutarde","quantity":""},{"name":"150 ml d’huile de colza vierge","quantity":""},{"name":"1 càc de vinaigre de cidre ou jus de citron","quantity":""},{"name":"Sel de l’Himalaya, poivre","quantity":""},{"name":"Optionnel : ail pressé, herbes fraîches","quantity":""}]$j$::jsonb, $j$["Tous les ingrédients doivent être à température ambiante — c’est la clé.","Mélangez le jaune d’oeuf et la moutarde dans un bol.","Versez l’huile en filet très fin en fouettant constamment, jusqu’à émulsion.","Quand la mayonnaise prend, vous pouvez verser l’huile plus rapidement.","Ajoutez le vinaigre ou le citron, salez, poivrez.","Conservez 3-4 jours au frigo dans un bocal fermé."]$j$::jsonb, 10),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Sauce bolognaise maison$t$, 'diner', $j$[{"name":"500 g de boeuf haché de qualité (bio, nourri à l’herbe)","quantity":""},{"name":"1 boîte de tomates concassées (800 g)","quantity":""},{"name":"2 càs de concentré de tomates","quantity":""},{"name":"1 oignon, 2 gousses d’ail","quantity":""},{"name":"1 carotte râpée","quantity":""},{"name":"1 branche de céleri (optionnel)","quantity":""},{"name":"Origan, basilic, laurier, thym","quantity":""},{"name":"Huile d’olive","quantity":""},{"name":"Sel de l’Himalaya, poivre","quantity":""}]$j$::jsonb, $j$["Faites revenir l’oignon émincé dans l’huile d’olive, 3 min. Ajoutez l’ail.","Ajoutez la viande hachée, faites-la dorer en l’émiettant.","Ajoutez la carotte râpée et le céleri, mélangez 2 min.","Ajoutez tomates, concentré et herbes. Salez, poivrez.","Laissez mijoter à feu doux minimum 45 min — plus c’est long, meilleur c’est.","Rectifiez l’assaisonnement en fin de cuisson."]$j$::jsonb, 15),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Soupe de légumes maison$t$, 'dejeuner', $j$[{"name":"1 litre de bouillon de légumes maison","quantity":""},{"name":"600 g de légumes au choix : courgette, poireau, carotte, brocoli, céleri-rave, butternut...","quantity":""},{"name":"1 oignon, 1 gousse d’ail","quantity":""},{"name":"Huile d’olive","quantity":""},{"name":"Sel de l’Himalaya, poivre","quantity":""},{"name":"Finition : huile d’olive crue, graines de courge, copeaux de parmesan, herbes fraîches","quantity":""}]$j$::jsonb, $j$["Faites revenir l’oignon émincé dans l’huile d’olive, 3 min.","Ajoutez les légumes coupés en morceaux, faites revenir 5 min.","Couvrez de bouillon, portez à ébullition, mijotez 20-25 min.","Mixez pour un velouté, ou laissez en morceaux selon votre goût.","Servez avec un filet d’huile d’olive crue et la garniture de votre choix."]$j$::jsonb, 10);
